query_text:
query TemplatesList($payload: TemplatesListSearchRequest!) {
  templatesList(payload: $payload) {
    id
    name
    artistId
    artistName
    artistNameForUrl
    isNew
    thumbnailUrl
    previewVideoFileUrl
    files {
      softwareName
      softwareVersionName
    },
    availableFormats {
      id
      displayName
    },
    nameForUrl
    resolutions
    isOriginal
  }
}

